# `"GrimoireUpgBonus" == d` in `_customBlock_Summoning`. Last updated in v2.43 Nov 6
grimoire_dont_scale = [9, 11, 26, 36, 39, 17, 32, 45]
grimoire_bones_list = ['Femurs', 'Ribcages', 'Craniums', 'Bovinae']

# NOTE: not Grimoire-exclusive -- Vault's own separate Knockout stack (own counter, own raw save
# index, a distinct mechanic; see _calculate_w1_upgrade_vault in account_calcs.py, or
# Vault.calculate() once vault-to-classes merges) also indexes into this same table for its own
# "Target: X" display. Whether that's deliberate shared game design or just code reuse isn't
# confirmed here -- only that the existing (pre-this-session) code already relies on it that way.
grimoire_stack_types = ['Knockout', 'Elimination', 'Annihiliation']
grimoire_coded_stack_monster_order = RANDOlist[104]


# Account-independent per-upgrade data, derived once from grimoire_upgrades_list above. Grimoire.__init__
# only needs to merge this with the two things that actually vary per account: level and the
# stack-count name suffix (see Stack Type below).
# NOTE: "Stack Type" here is purely "does the raw name carry a (#) placeholder", independent of
# grimoire_stack_types (used later, in GrimoireUpgrade.calculate(), to gate the "Target:$" monster
# substitution) -- keep these two checks separate, they are not the same gate.
grimoire_upgrades = []
for _index, _upgrade_values in enumerate(grimoire_upgrades_list):
    _clean_name = _upgrade_values[0].replace('(Tap_for_more_info)', '').replace('製', '').replace('_', ' ').rstrip()
    if _clean_name == 'Ripped Page':
        continue
    _stack_type = _clean_name.split('!')[0] if '(#)' in _clean_name else None
    grimoire_upgrades.append({
        "Name": _clean_name,
        "Index": _index,
        "Stack Type": _stack_type,
        "Cost Base": int(_upgrade_values[1]),
        "Cost Increment": float(_upgrade_values[2]),
        "Bone Index": int(_upgrade_values[3]),
        "Max Level": int(_upgrade_values[4]),
        "Value Per Level": int(_upgrade_values[5]),
        "Unlock Requirement": int(_upgrade_values[6]),
        "Description": _upgrade_values[9].replace('_', ' '),
        "Scaling Value": _index not in grimoire_dont_scale,
    })
